export interface Row {
  [column: string]: unknown;
}

export function toCsvLine(row: Row, columns: string[]): string {
  return columns.map((c) => '"' + String(row[c] ?? '').replaceAll('"', '""') + '"').join(',');
}

export const ROWS_PER_FILE = 5000;

export function exportCsv(rows: Row[], columns: string[], dir: string): string[] {
  const written: string[] = [];
  for (let start = 0, part = 1; start < rows.length; start += ROWS_PER_FILE, part++) {
    const chunk = rows.slice(start, start + ROWS_PER_FILE);
    const name = part === 1 ? 'export.csv' : 'part-' + part + '.csv';
    const lines = [columns.join(','), ...chunk.map((r) => toCsvLine(r, columns))];
    writeFileSync(dir + '/' + name, lines.join('\n') + '\n');
    written.push(name);
  }
  return written;
}
